from pathlib import Path
import json,re,subprocess

tid='DEV-PRED-AUTOBUILD-PINFIX-20260930-E005'
mirror=Path.home()/'.local/share/prediction-project-executor/repo'
code='70000000000000000000000000000000000000ff'

def run(args):
    cp=subprocess.run(['git',*args],cwd=mirror,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
    return cp.returncode,cp.stdout

if not mirror.is_dir():
    code='7000000000000000000000000000000000000001'
else:
    rc,head=run(['rev-parse','FETCH_HEAD'])
    if rc!=0:
        code='7000000000000000000000000000000000000002'
    else:
        remote=head.strip()
        rc,raw=run(['show',remote+':control/project_tasks/'+tid+'.json'])
        if rc!=0:
            code='7000000000000000000000000000000000000003'
        else:
            try: obj=json.loads(raw)
            except Exception:
                code='7000000000000000000000000000000000000004'; obj=None
            if obj is not None:
                allowed={'schema','task_id','source_commit','intelligence_tier','issuer','safety','capabilities','working_directory','operations','timeout_seconds','notes','build_id'}
                required={'schema','task_id','source_commit','intelligence_tier','issuer','safety','capabilities','operations'}
                caps={'read_repository','write_worktree','run_project_python','run_tests','local_git','read_runtime','write_runtime','user_service_manage','read_logs'}
                if set(obj)-allowed: code='7000000000000000000000000000000000000005'
                elif not required.issubset(obj): code='7000000000000000000000000000000000000006'
                elif obj.get('schema')!='PREDICTION_PROJECT_TASK_V1' or obj.get('task_id')!=tid: code='7000000000000000000000000000000000000007'
                elif not re.fullmatch(r'[0-9a-f]{40}',str(obj.get('source_commit') or '')): code='7000000000000000000000000000000000000008'
                elif obj.get('intelligence_tier') not in {'A','B','C'}: code='7000000000000000000000000000000000000009'
                elif not isinstance(obj.get('issuer'),dict) or set(obj['issuer'])!={'model','reasoning_level'}: code='700000000000000000000000000000000000000a'
                elif not isinstance(obj.get('safety'),dict): code='700000000000000000000000000000000000000b'
                elif any(obj['safety'].get(k) is not False for k in ('live_trading','paid_actions','wallet_actions','remote_git_write','credential_write')): code='700000000000000000000000000000000000000c'
                elif not isinstance(obj.get('capabilities'),list) or not obj['capabilities'] or len(set(obj['capabilities']))!=len(obj['capabilities']): code='700000000000000000000000000000000000000d'
                elif any(c not in caps for c in obj['capabilities']): code='700000000000000000000000000000000000000e'
                elif not isinstance(obj.get('operations'),list) or not obj['operations'] or len(obj['operations'])>40: code='700000000000000000000000000000000000000f'
                elif not isinstance(obj.get('timeout_seconds',900),int) or not 1<=obj.get('timeout_seconds',900)<=1800: code='7000000000000000000000000000000000000010'
                else:
                    rc,_=run(['cat-file','-e',str(obj['source_commit'])+'^{commit}'])
                    code='7000000000000000000000000000000000000011' if rc!=0 else '7000000000000000000000000000000000000012'
print(code)
